"""
RRC Protocol Messages Definition Module for PCAP Analysis.
This module provides predefined RRC (Radio Resource Control) message definitions and factory functions
for creating awaited messages used in PCAP file analysis.
The module defines AwaitedMessage objects that can be used to verify the presence and correctness of
specific RRC protocol messages in network traffic captures.

:copyright:     Nokia Networks
:author:        Piotr Brzezicki, Mateusz Potoniec
:maintainer:    Piotr Brzezicki, Mateusz Potoniec
:contact:       piotr.brzezicki@nokia.com, mateusz.potoniec@nokia.com

Usage:
    from taf.rfrl.utilities.parsers.pcap_checker import Checker
    from taf.rfrl.utilities.parsers.pcap_checker.utils import PcapProvider
    from taf.rfrl.utilities.parsers.pcap_checker.messages import rrc_messages

    phys_cell_id = '50'
    awaited_messages = [
        rrc_messages.RRC_SETUP_REQUEST,
        rrc_messages.RRC_SETUP,
        rrc_messages.RRC_SETUP_COMPLETE,
        rrc_messages.RRC_RECONFIGURATION,
        rrc_messages.create_measurement_report_pci(phys_cell_id)
    ]

    forbidden_messages = [rrc_messages.RRC_RELEASE]

    pcap_provider = PcapProvider()
    checker = Checker(pcap_provider=pcap_provider)
    checker.expect_flow(
        pcap_file=pcap_file,
        display_filter='nr-rrc',
        awaited_messages=awaited_messages,
        forbidden_messages=forbidden_messages
    )
"""


from taf.rfrl.utilities.parsers.pcap_checker.checker import AwaitedMessage
from taf.rfrl.utilities.parsers.pcap_checker.inspectors import HasInspector


RRC_SETUP_REQUEST = AwaitedMessage(
    name='RRCSetupRequest',
    find_by=[HasInspector('nr-rrc.rrcSetupRequest_element')],
    verify_by=[],
)


RRC_SETUP = AwaitedMessage(
    name='RRCSetup',
    find_by=[HasInspector('nr-rrc.rrcSetup_element')],
    verify_by=[],
)


RRC_SETUP_COMPLETE = AwaitedMessage(
    name='RRCSetupComplete',
    find_by=[HasInspector('nr-rrc.rrcSetupComplete_element')],
    verify_by=[],
)


RRC_RELEASE = AwaitedMessage(
    name='RRCRelease',
    find_by=[HasInspector('nr-rrc.rrcRelease_element')],
    verify_by=[],
)


RRC_REESTABLISHMENT = AwaitedMessage(
    name='RRCReestablishment',
    find_by=[HasInspector('nr-rrc.rrcReestablishmentRequest_element')],
    verify_by=[],
)


RRC_RECONFIGURATION = AwaitedMessage(
    name='RRCReconfiguration',
    find_by=[HasInspector('nr-rrc.rrcReconfiguration_element')],
    verify_by=[],
)


RRC_RECONFIGURATION_COMPLETE = AwaitedMessage(
    name='RRCReconfigurationComplete',
    find_by=[HasInspector('nr-rrc.rrcReconfigurationComplete_element')],
    verify_by=[],
)


UE_CAPABILITY_INFORMATION = AwaitedMessage(
    name='ueCapabilityInformation',
    find_by=[HasInspector('nr-rrc.ueCapabilityInformation_element')],
    verify_by=[],
)


RRC_RECONFIGURATION_SCELL_ADD = AwaitedMessage(
    name='NRDC SCG Setup',
    find_by=[HasInspector('nr-rrc.sCellToAddModList')],
    verify_by=[],
)


RRC_RECONFIGURATION_SCELL_RELEASE = AwaitedMessage(
    name='NRDC SCG Setup',
    find_by=[HasInspector('nr-rrc.sCellToReleaseList')],
    verify_by=[],
)


RRC_RECONFIGURATION_SCG_RELEASE = AwaitedMessage(
    name='RRCReconfiguration',
    find_by=[HasInspector('nr-rrc.rrcReconfiguration_element')],
    verify_by=[
        HasInspector('nr-rrc.mrdc_SecondaryCellGroupConfig', '0'),
        HasInspector('nr-rrc.release_element'),
    ],
)


RRC_RECONFIGURATION_NRDC_SCG_CONFIG = AwaitedMessage(
    name='NRDC SCG Setup',
    find_by=[HasInspector('nr-rrc.mrdc_SecondaryCellGroupConfig', '1')],
    verify_by=[],
)


def create_measurement_report_pci(phys_cell_id: str) -> AwaitedMessage:
    """
    Factory function to create an AwaitedMessage for MeasurementReport with a specific physical cell ID.

    :param phys_cell_id: The physical cell ID to verify in the message.
    :return: An AwaitedMessage instance with the specified physical cell ID verification.
    """

    return AwaitedMessage(
        name='measurementReport',
        find_by=[HasInspector('nr-rrc.measurementReport_element')],
        verify_by=[HasInspector('nr-rrc.physCellId', str(phys_cell_id))],
    )


def create_rrc_setup_bwp(
        location_and_bandwidth: str,
        bwp_id: str = '1',
        downlink_bwp_id: str = '1',
        uplink_bwp_id: str = '1') -> AwaitedMessage:
    """
    Factory function to create an AwaitedMessage for RRCSetup with a specific location and bandwidth.

    :param location_and_bandwidth: The location and bandwidth to verify in the message.
    :param bwp_id: The BWP ID to verify in the message. Default is '1'.
    :param downlink_bwp_id: The first active downlink BWP ID to verify in the message. Default is '1'.
    :param uplink_bwp_id: The first active uplink BWP ID to verify in the message. Default is '1'.
    :return: An AwaitedMessage instance with the specified location and bandwidth verification.
    """

    return AwaitedMessage(
        name='RRCSetup',
        find_by=[HasInspector('nr-rrc.rrcSetup_element')],
        verify_by=[
            HasInspector('nr-rrc.bwp_Id', str(bwp_id)),
            HasInspector('nr-rrc.locationAndBandwidth', str(location_and_bandwidth)),
            HasInspector('nr-rrc.firstActiveDownlinkBWP_Id', str(downlink_bwp_id)),
            HasInspector('nr-rrc.firstActiveUplinkBWP_Id', str(uplink_bwp_id)),
        ],
    )


def create_rrc_reconfiguration_bwp(
        location_and_bandwidth: str,
        bwp_id: str = '1',
        downlink_bwp_id: str = '1',
        uplink_bwp_id: str = '1') -> AwaitedMessage:
    """
    Factory function to create an AwaitedMessage for RRCReconfiguration with a specific location and bandwidth.

    :param location_and_bandwidth: The location and bandwidth to verify in the message.
    :param bwp_id: The BWP ID to verify in the message. Default is '1'.
    :param downlink_bwp_id: The first active downlink BWP ID to verify in the message. Default is '1'.
    :param uplink_bwp_id: The first active uplink BWP ID to verify in the message. Default is '1'.
    :return: An AwaitedMessage instance with the specified location and bandwidth verification.
    """

    return AwaitedMessage(
        name='RRCReconfiguration',
        find_by=[HasInspector('nr-rrc.rrcReconfiguration_element')],
        verify_by=[
            HasInspector('nr-rrc.bwp_Id', str(bwp_id)),
            HasInspector('nr-rrc.locationAndBandwidth', str(location_and_bandwidth)),
            HasInspector('nr-rrc.firstActiveDownlinkBWP_Id', str(downlink_bwp_id)),
            HasInspector('nr-rrc.firstActiveUplinkBWP_Id', str(uplink_bwp_id)),
        ],
    )
